                'crop_varieties_ur' => 'ارکا سوریا مکھّی زیادہ پیداوار دینے والی قسم ہے۔ پوسا وشواس بیماریوں کے خلاف مزاحمت رکھنے والی قسم ہے۔ پنجاب پمپکن-1 مقامی طور پر بہتر کی گئی قسم ہے۔ کاشی ہریٹ ایک ہائبرڈ قسم ہے۔',
                'nutritional_value_ur' => 'وٹامن اے: بینائی اور جلد کی صحت کے لیے مفید ہے۔ وٹامن سی: قوتِ مدافعت مضبوط بنانے میں مدد دیتا ہے۔ غذائی ریشہ: ہاضمہ بہتر بنانے میں مدد دیتا ہے۔ پوٹاشیم: بلڈ پریشر کو متوازن رکھنے میں مدد دیتا ہے۔ اینٹی آکسیڈنٹس: جسم کے خلیوں کو نقصان سے بچانے میں مدد دیتے ہیں۔',
                'importance_of_crop_ur' => 'کدو ایک اہم سبزی کی فصل ہے جو گھریلو خوراک اور تجارتی منڈیوں میں استعمال ہوتی ہے۔ اس میں موجود غذائی اجزا اسے روزمرہ غذا کا مفید حصہ بناتے ہیں۔ کدو کی کاشت کسانوں کے لیے آمدنی کا ذریعہ بھی بنتی ہے۔',
            ],
        ];

        foreach ($records as $record) {
            $crop = Crop::where('name', $record['crop_name'])->first();
            if (!$crop) continue;

            $crop->name_ur = $record['name_ur'];
            $crop->save();

            $detail = CropDetail::firstOrNew(['crop_id' => $crop->id]);
            $detail->crop_name = $crop->name;
            $detail->crop_name_ur = $record['name_ur'];
            foreach ($record as $field => $value) {
                if ($field === 'crop_name' || $field === 'name_ur') continue;
                $detail->{$field} = $value;
            }
            $detail->urdu_completed = collect([
                'crop_name_ur', 'introduction_ur', 'basic_information_ur', 'sowing_season_ur',
                'harvesting_season_ur', 'climate_requirements_ur', 'soil_requirements_ur',
                'land_preparation_ur', 'seed_selection_ur', 'seed_rate_ur',
                'irrigation_requirements_ur', 'fertilizer_requirements_ur', 'growing_stages_ur',
                'types_of_crop_ur', 'crop_varieties_ur', 'nutritional_value_ur',
                'importance_of_crop_ur',
            ])->every(fn ($field) => filled($detail->{$field}));
            $detail->save();
            $crop->urdu_completed = $detail->urdu_completed;
            $crop->save();
        }
    }
}
